#!/usr/bin/env node
// ============================================================================
//  tools/c1/drive_c1_engine.mjs — run a C1 browser step file on chrome / firefox / webkit (C1 closure, 2026-11-23).
//  Same step format as review/tactic-book-3a/deterministic-math-c1/browser/drive.mjs (generated by mk_c1.mjs):
//    {vp:[w,h,mobile]} {nav:url} {tap:testid} {tapText:regex} {wait:ms} {until:expr, ms} {js:body} {shot:path} {save:{expr,path}}
//  {vp} must come before {nav} (Playwright fixes the viewport per fresh context). Each run starts with a fresh profile.
//  Usage: node tools/c1/drive_c1_engine.mjs --engine=firefox --steps=<steps.json>
// ============================================================================
import fs from "node:fs";
import { openEngine } from "./c1_engines.mjs";

const arg = (k, d) => { const a = process.argv.find((x) => x.startsWith(`--${k}=`)); return a ? a.slice(k.length + 3) : d; };
const name = arg("engine", "chrome"), steps = JSON.parse(fs.readFileSync(arg("steps"), "utf8"));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const E = await openEngine(name, { port: 9479 });
console.log("engine", name, E.ua, E.browserVersion ?? "");
const guard = "window.confirm=()=>true; window.alert=()=>{}; return 1;";
try {
  for (const s of steps) {
    if (s.vp) await E.setViewport(s.vp[0], s.vp[1], !!s.vp[2]);
    if (s.nav) { await E.goto(s.nav); await sleep(3500); await E.evaluate(guard); }
    if (s.tap || s.tapText) {
      const sel = s.tap ? `document.querySelector('[data-testid="${s.tap}"]')` : `[...document.querySelectorAll('button,[role=button],a')].find(b=>new RegExp(${JSON.stringify(s.tapText)}).test((b.innerText||'').trim())&&!b.disabled)`;
      const r = await E.evaluate(`const e=${sel}; if(!e) return null; e.scrollIntoView({block:'center'}); const b=e.getBoundingClientRect(); return {x:b.x+b.width/2,y:b.y+b.height/2};`);
      if (!r) console.log("tap", s.tap ?? s.tapText, "missing"); else { await E.mouseClick(r.x, r.y); console.log("tap", s.tap ?? s.tapText, "ok", Math.round(r.x), Math.round(r.y)); }
    }
    if (s.wait) await sleep(s.wait);
    if (s.until) { const t = Date.now(); let ok = false; while (Date.now() - t < (s.ms ?? 60000)) { if (await E.evaluate(`return !!(${s.until});`)) { ok = true; break; } await sleep(1000); } console.log("until", s.until.slice(0, 60), ok, ((Date.now() - t) / 1000).toFixed(1) + "s"); }
    if (s.js) console.log("js", await E.evaluate(s.js));
    if (s.shot) { await E.screenshot(s.shot); console.log("shot", s.shot); }
    if (s.save) { const v = await E.evaluate(s.save.expr); fs.writeFileSync(s.save.path, typeof v === "string" ? v : JSON.stringify(v)); console.log("save", s.save.path, String(v).length); }
  }
} finally { await E.close(); }
